package dev.zomboidmelee.boxing;
import net.minecraft.client.model.*;import net.minecraft.client.model.geom.ModelPart;import net.minecraft.client.renderer.entity.player.PlayerRenderer;import net.minecraft.client.renderer.MultiBufferSource;import net.minecraft.client.player.AbstractClientPlayer;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;
/** Typed accesses intentionally bypass subclass GeoBone fields called rightArm/leftArm. */
public final class BoxingArms17{
 public static void pose(Object object,int side,float x,float y,float z){if(!(object instanceof HumanoidModel<?> model))return;ModelPart arm=side==0?model.rightArm:model.leftArm;if(arm==null)return;arm.xRot=x;arm.yRot=y;arm.zRot=z;if(object instanceof PlayerModel<?> player){ModelPart sleeve=side==0?player.rightSleeve:player.leftSleeve;if(sleeve!=null)sleeve.copyFrom(arm);}}
 public static void draw(Object renderer,Object stack,Object buffers,int light,Object player,int side,double extension){PoseStack p=(PoseStack)stack;int sign=side==0?1:-1;p.pushPose();try{p.translate(sign*(.48-.12*extension),-.65+.14*extension,-.10-.42*extension);p.mulPose(Axis.YP.rotationDegrees((float)(sign*(20-16*extension))));p.mulPose(Axis.XP.rotationDegrees((float)(-55-12*extension)));p.mulPose(Axis.ZP.rotationDegrees((float)(sign*3*extension)));p.translate(sign*(5.0/16),-2.0/16,0);if(side==0)((PlayerRenderer)renderer).renderRightHand(p,(MultiBufferSource)buffers,light,(AbstractClientPlayer)player);else((PlayerRenderer)renderer).renderLeftHand(p,(MultiBufferSource)buffers,light,(AbstractClientPlayer)player);}finally{p.popPose();}}
 public static void flinch(Object object,float amount){if(!(object instanceof HumanoidModel<?> m))return;if(m.body!=null)m.body.xRot+=.22f*amount;if(m.head!=null){m.head.xRot-=.3f*amount;m.head.zRot+=.12f*amount;}if(m.rightArm!=null)m.rightArm.xRot-=.2f*amount;if(m.leftArm!=null)m.leftArm.xRot-=.2f*amount;}
 public static void leg(Object renderer,Object stack,Object buffers,int light,Object player,double progress){Object object=R.call(renderer,"getModel");if(!(object instanceof HumanoidModel<?> model)||model.rightLeg==null)return;ModelPart leg=model.rightLeg;float x=leg.xRot,y=leg.yRot,z=leg.zRot;PoseStack p=(PoseStack)stack;p.pushPose();try{double stomp=Math.sin(Math.PI*Math.min(1,progress));p.translate(.28,-.72-.28*stomp,-.5-.32*stomp);p.mulPose(Axis.XP.rotationDegrees(-72));p.translate(-.12,-.75,0);leg.xRot=leg.yRot=leg.zRot=0;Object texture=R.call(R.call(player,"getSkin"),"texture");Object type=R.call(R.type("net.minecraft.client.renderer.RenderType"),"entitySolid",texture);Object consumer=R.call(buffers,"getBuffer",type);R.call(leg,"render",p,consumer,light,655360);}finally{leg.xRot=x;leg.yRot=y;leg.zRot=z;p.popPose();}}
 public static void flush(Object buffers){((MultiBufferSource.BufferSource)buffers).endBatch();}
}
